import{_ as s,o as t,c as i,a5 as a}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Architecture et limites de la démo navigateur","description":"","frontmatter":{"title":"Architecture et limites de la démo navigateur","docId":"developer.demo","translationKey":"developer.demo","locale":"fr","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"9aec97bb1d4bc623c4f9b64478668231fad203638ef4b6eb62369d8e7eebd6ec","translationRevision":"7536c967ad6e7fbc6ec6ba3ee66ab4da9e6c7bc79567df03f3151936b6efedb5","order":140},"headers":[],"relativePath":"fr/developer/demo.md","filePath":"fr/developer/demo.md","lastUpdated":1794615808000}'),n={name:"fr/developer/demo.md"};function r(l,e,o,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="browser-demo-architecture-and-limits" tabindex="-1">Architecture et limites de la démo navigateur <a class="header-anchor" href="#browser-demo-architecture-and-limits" aria-label="Permalink to &quot;Architecture et limites de la démo navigateur {#browser-demo-architecture-and-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Explorer l’interface réelle de l’application avec des données synthétiques dans un navigateur. Utilisez Bun 1.4.4 et l’installation verrouillée du dépôt. L’entrée explicite de démo fonctionne indépendamment de Rust, des comptes et d’un hôte actif. Son runtime et ses vérifications de validation navigateur font partie de ce dépôt.</p><h2 id="build-and-inspect" tabindex="-1">Compiler et examiner <a class="header-anchor" href="#build-and-inspect" aria-label="Permalink to &quot;Compiler et examiner {#build-and-inspect}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>Pour un aperçu local non commité, utilisez <code>TIKTOOLS_SITE_ALLOW_DIRTY=1 bun scripts/task.ts site build</code>. Son manifeste est marqué comme modifié et la publication le rejette. L’assemblage final exige que les deux bundles indiquent le même SHA Git propre et la même base ; recompilez après le commit. Lancez un serveur de développement ou d’aperçu uniquement lorsque le travail navigateur local est souhaité. <code>docs</code> possède VitePress et <code>demo</code> le bundle applicatif navigateur ; <code>site build</code> les assemble en un site statique. L’espace documentaire conserve sa dépendance VitePress séparément de la chaîne Vite 8 de l’application. Les commandes ne doivent ni installer silencieusement des dépendances ni invoquer Cargo.</p><h2 id="preserve-the-application-boundary" tabindex="-1">Préserver la frontière applicative <a class="header-anchor" href="#preserve-the-application-boundary" aria-label="Permalink to &quot;Préserver la frontière applicative {#preserve-the-application-boundary}&quot;">​</a></h2><p><code>src/web/app/mount-workspace.ts</code> fournit la fabrique partagée application/Pinia/routeur ; l’importer ne monte rien et ne choisit pas de transport. L’initialisation explicite de démo fournit <code>src/web/demo/runtime/transport.ts</code> à la frontière partagée <code>ControlTransport</code>/client de contrôle. Les fixtures initiales pures se trouvent dans <code>demo/fixtures/base-host.ts</code>, indépendamment de Playwright. <code>shared/lib/app-storage.ts</code> et <code>demo/storage.ts</code> fournissent des adaptateurs de stockage isolés pour que les réinitialisations ne puissent pas effacer les préférences natives ou une autre instance de démo. Les pages, widgets et fonctionnalités doivent utiliser leurs stores d’entité existants et les appels <code>src/web/shared/api</code>. Ne créez pas une seconde application imitée, n’injectez pas de fausses API natives au démarrage natif ordinaire et ne laissez pas les requêtes de démo atteindre un véritable hôte.</p><p><code>demo/scenarios.ts</code> valide 11 identifiants de scénario et les routes/langues/visites autorisées. Les exemples ciblés acceptent aussi <code>embed=connection|feed|automation|points|overlays</code>. Chaque panneau intégré exige la route correspondante et ne peut pas lancer de visite ; les combinaisons invalides sont rejetées par la validation. L’entrée intégrée masque la navigation de l’espace de travail et la barre complète de la démo, tout en conservant les véritables composants de page, les stores et le runtime simulé. <code>runtime/host.ts</code> enregistre des gestionnaires de méthodes explicites ; la découverte liste ces gestionnaires, les identifiants de requête sont repris dans <code>rpc-response</code> et les effets non pris en charge renvoient immédiatement une erreur. L’hôte initialise des enregistrements fictifs et avance une horloge fixe d’un pas par Next event. Play et Next event connectent d’abord le créateur fictif via la RPC simulée si nécessaire, puis livrent un événement immédiat. Play continue toutes les deux secondes ; Pause arrête la production. La barre d’outils affiche l’état de lecture et le nombre d’événements. Le flux s’arrête à 300 pas et conserve au maximum 60 événements de flux et 60 exécutions. Les files de réponses et les enregistrements stockés ont des limites distinctes.</p><p>Reset efface uniquement le préfixe courant <code>tiktools.demo.&lt;instance&gt;.*</code> et recharge le cadre. Le rechargement réinitialise les singletons de modules, journaux, i18n et diagnostics. Les cadres intégrés reçoivent des identifiants d’instance distincts. Quitter la page démonte Vue, libère les stores, détache le client/transport et supprime les deux temporisateurs. La démo n’installe pas de pont <code>window.ipc</code> et n’effectue ni HTTP arbitraire, shell, RCON, exécution de scripts de visiteurs ou installation de mise à jour native. Sa CSP rejette les connexions réseau. Les modèles de journal et la simulation des filtres utilisent des fonctions partagées pures ; ce sont des exemples du contrat de l’interface, pas un remplacement de l’exécution Rust.</p><p>L’entrée partagée <code>startTour(id, {router, capabilities, taskState})</code> et le <code>tourRegistry</code> exporté se trouvent dans <code>src/web/features/guided-help/index.ts</code>. Sept visites versionnées utilisent des cibles de page stables et des catalogues séparés pour chaque langue prise en charge. Elles chargent Driver.js uniquement sur demande, limitent les cibles à l’espace de travail, respectent la réduction des animations, restaurent le focus et annulent les attentes bornées lors de la navigation. Fermer une visite ne termine jamais une tâche et n’exécute aucune action applicative. La sélection d’un tutoriel nomme la tâche complète, prépare le scénario correspondant et suspend la lecture avant de commencer. La commande de fermeture de Driver ferme le guide ; la barre d’outils rapporte le résultat. Reset efface la progression versionnée de cette instance.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>La démo illustre la navigation, l’édition locale, la présentation des événements et les états de récupération pris en charge par son modèle de scénario. Elle ne valide pas de vraies sessions TikTok, une source navigateur OBS, le comportement Wry/natif, un serveur de production ou plusieurs PC. Rankings reste masqué ; Automations Changes est uniquement local, Variables avec examen est un vrai travail produit natif, Overlay Changes reste un travail ultérieur non fusionné et les conditions d’installation automatique des mises à jour sont expérimentales.</p><h2 id="components-and-markdown" tabindex="-1">Composants et Markdown <a class="header-anchor" href="#components-and-markdown" aria-label="Permalink to &quot;Composants et Markdown {#components-and-markdown}&quot;">​</a></h2><p><code>docs/examples/*.vue</code> fournit à la fois le catalogue rendu et les extraits sources. Les petits boutons s’affichent directement dans Markdown sans styles globaux du bureau. Les boîtes de dialogue avec état, exemples de disposition et pages applicatives utilisent <code>DemoFrame</code>, qui construit des URL validées tenant compte de la base. Par défaut, les exemples des articles chargent leur iframe sur demande. Placez les exemples ciblés à côté des instructions qu’ils illustrent :</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fr&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Essayer le panneau de connexion LIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>La propriété <code>panel</code> sélectionne le paramètre <code>embed</code> et la route correspondante. Avant l’activation, un exemple d’article affiche un lanceur neutre avec son titre et sa commande de chargement ; il n’imite pas l’interface applicative. Un clic charge l’interface réelle. Chaque cadre reçoit un identifiant d’instance isolé et la réinitialisation n’efface que cette instance. Le lien vers la démo complète retire le mode intégré et ouvre l’espace de travail entier. Conservez les étapes explicatives et les résultats attendus en Markdown pour que l’article reste utile avant le chargement de l’exemple.</p><p>La page d’accueil charge automatiquement l’espace de travail réel avec <code>autoload</code> et <code>minimal</code>. Ses cinq onglets permettent de choisir la connexion, l’activité en direct, les automatisations, les incrustations ou les points, avec un seul iframe actif monté à la fois. Changer d’onglet remplace ce cadre plutôt que de laisser cinq applications fonctionner. Aucune imitation de l’interface ni aucun aperçu de scène n’est utilisé.</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DemoFrame</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> scenario</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> locale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fr&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> panel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Essayer TikTools&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> autoload</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> minimal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><code>autoload</code> démarre l’iframe après le montage du composant ; <code>minimal</code> masque l’en-tête d’article, les commandes de lancement et le pied de tâche du cadre pour son intégration dans la zone de démonstration de l’accueil. Réservez la hauteur de cette zone avant le chargement, en utilisant <code>--demo-frame-height</code> de manière cohérente pour son état de chargement et son iframe, afin d’éviter de déplacer le contenu environnant. L’interface réelle et le stockage isolé se comportent de la même façon dans les deux modes. L’option publique <code>VITE_TIKTOOLS_PUBLIC_UI_KIT=1</code> expose le catalogue de composants sans activer tous les outils de développement du bureau.</p><h2 id="recovery-and-verification" tabindex="-1">Récupération et vérification <a class="header-anchor" href="#recovery-and-verification" aria-label="Permalink to &quot;Récupération et vérification {#recovery-and-verification}&quot;">​</a></h2><p>Réinitialisez un scénario après une lacune ou erreur délibérément simulée. S’il contacte un service externe, arrêtez-le et réparez la frontière de transport. Vérifiez séparément le contenu, la compilation de démo et l’assemblage du site ; une compilation documentaire ne prouve pas la correction native. Les <a href="./testing.html">tests</a> distinguent les preuves de faux hôte, navigateur, Rust et validation manuelle.</p>`,22)])])}const m=s(n,[["render",r]]);export{h as __pageData,m as default};
